#include <stdio.h>
#include <stdint.h>

#define HASH_SIZE (1u << 20)
#define HASH_MASK (HASH_SIZE - 1)

static uint64_t table[HASH_SIZE];

static inline uint64_t mix64(uint64_t x) {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline uint64_t make_key(int type, int len, uint64_t code) {
    return ((uint64_t)type << 60) | ((uint64_t)len << 56) | code;
}

static inline int contains(uint64_t key) {
    uint32_t idx = (uint32_t)(mix64(key) & HASH_MASK);
    while (table[idx] != 0) {
        if (table[idx] == key) return 1;
        idx = (idx + 1) & HASH_MASK;
    }
    return 0;
}

static inline void insert(uint64_t key) {
    uint32_t idx = (uint32_t)(mix64(key) & HASH_MASK);
    while (table[idx] != 0) {
        if (table[idx] == key) return;
        idx = (idx + 1) & HASH_MASK;
    }
    table[idx] = key;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char s[16];
    uint64_t pref[11], suff[11];

    for (int k = 0; k < N; ++k) {
        scanf("%s", s);

        pref[0] = 0;
        for (int i = 0; i < 10; ++i) {
            pref[i + 1] = pref[i] * 26 + (uint64_t)(s[i] - 'a');
        }

        for (int len = 1; len <= 10; ++len) {
            uint64_t code = 0;
            for (int i = 10 - len; i < 10; ++i) {
                code = code * 26 + (uint64_t)(s[i] - 'a');
            }
            suff[len] = code;
        }

        uint64_t complete_key = make_key(3, 10, pref[10]);
        if (contains(complete_key)) {
            printf("%s\n", s);
            return 0;
        }

        for (int L = 1; L <= 9; ++L) {
            uint64_t suffix_part_key = make_key(2, L, pref[L]);
            if (contains(suffix_part_key)) {
                int R = 10 - L;
                uint64_t prefix_part_key = make_key(1, R, suff[R]);
                if (contains(prefix_part_key)) {
                    printf("%s\n", s);
                    return 0;
                }
            }
        }

        insert(complete_key);

        for (int len = 1; len <= 9; ++len) {
            insert(make_key(1, len, pref[len]));
            insert(make_key(2, len, suff[len]));
        }
    }

    printf("ok\n");
    return 0;
}
